S = "Hakeem Force Academy"
QS = [
(S, "Which angel brought the message (revelation) of Allah to the Holy Prophet (S.A.W.)?", ["Hazrat Mikail (A.S.)", "Hazrat Jibrail (A.S.)", "Hazrat Israfil (A.S.)", "Hazrat Izrail (A.S.)"], 1, "Hazrat Jibrail (A.S.) carried the revelation from Allah to the Prophet (S.A.W.). He is the angel of revelation.", "Hazrat Jibrail (A.S.) is also called Ruh-ul-Amin.", [1174]),
(S, "Which woman of the Makhzum tribe, caught for theft, was brought before the Holy Prophet (S.A.W.) for judgement?", ["Fatima bint Aswad", "Fatima bint Muhammad", "Hind bint Utba", "Khadija bint Khuwaylid"], 0, "A noble woman of Banu Makhzum named Fatima bint Aswad was caught stealing and brought to the Prophet (S.A.W.). He said the law applies equally to all and that even if Fatima, daughter of Muhammad, stole, her hand would be cut.", "Some candidates confuse her with Fatima bint Khuwaylid, which is incorrect.", [4076]),
(S, "Which of the following is the tallest completed building in Karachi?", ["Habib Bank Plaza", "Bahria Icon Tower", "MCB Tower", "Dolmen Tower"], 1, "Bahria Icon Tower in Karachi has 62 floors and is the tallest completed building in the city. Older towers such as Habib Bank Plaza are shorter.", "A taller 82-storey tower called Burj Quaid has been announced in DHA City Karachi but is not yet built.", [3209]),
(S, "A is the father of B, but B is not the son of A. What is B to A?", ["Daughter", "Nephew", "Brother", "Wife"], 0, "B is a child of A, but not a son, so B must be a daughter.", "In blood relation questions, check every possible relation before choosing.", [1320]),
(S, "A boy buys a book for Rs 30 and sells it for Rs 40. What is his profit percentage?", ["25%", "30%", "33.33%", "10%"], 2, "Profit = 40 - 30 = Rs 10. Profit percentage = 10 / 30 x 100 = 33.33%.", "Profit percentage is always calculated on the cost price.", [1312]),
(S, "Who were the first and second Caliphs of Islam?", ["Hazrat Abu Bakr and Hazrat Umar (R.A.)", "Hazrat Umar and Hazrat Uthman (R.A.)", "Hazrat Abu Bakr and Hazrat Ali (R.A.)", "Hazrat Uthman and Hazrat Ali (R.A.)"], 0, "Hazrat Abu Bakr Siddiq (R.A.) was the first Caliph and Hazrat Umar Farooq (R.A.) was the second.", "The four Rightly Guided Caliphs in order were Abu Bakr, Umar, Uthman and Ali (R.A.).", [4329]),
(S, "What is the fraction 11/7 called?", ["Proper fraction", "Improper fraction", "Decimal fraction", "Unit fraction"], 1, "In 11/7 the numerator 11 is larger than the denominator 7, so it is an improper fraction. It equals 1 and 4/7.", "A proper fraction has a numerator smaller than its denominator, such as 3/7.", [454]),
(S, "Who is called Jame-ul-Quran, the one who collected the Quran?", ["Hazrat Abu Bakr (R.A.)", "Hazrat Umar (R.A.)", "Hazrat Uthman (R.A.)", "Hazrat Ali (R.A.)"], 2, "Hazrat Uthman (R.A.) is called Jame-ul-Quran because he had the Quran compiled in one standard form and copies sent to the main cities.", "The Quran was first collected in one book under Hazrat Abu Bakr (R.A.) with Zaid bin Thabit as head of the committee.", [4170]),
(S, "If there are 2 cows and the number of camels is twice the number of cows, how many camels are there?", ["2", "6", "8", "4"], 3, "Camels = 2 x 2 = 4.", "Always read whether the question asks for camels only or for the total animals.", [747]),
(S, "How many times were the modern Olympic Games cancelled because of world wars?", ["Once", "Twice", "Three times", "Four times"], 2, "The Games were cancelled in 1916 (World War I), and in 1940 and 1944 (World War II). That makes three times.", "The Olympics were postponed, not cancelled, in 2020 and held in Tokyo in 2021.", [1278, 2217, 3508]),
(S, "On what date was the 1956 Constitution of Pakistan abrogated?", ["7 October 1958", "23 March 1956", "14 August 1958", "5 July 1977"], 0, "President Iskander Mirza abrogated the 1956 Constitution on 7 October 1958 and imposed martial law.", "General Ayub Khan took over from Iskander Mirza a few days later, on 27 October 1958.", [2304]),
(S, "What was the old (first) capital of Pakistan?", ["Lahore", "Rawalpindi", "Karachi", "Peshawar"], 2, "Karachi was the first capital of Pakistan after 1947. The capital was later moved to Islamabad, with Rawalpindi acting as temporary capital in the 1960s.", "Islamabad became the capital in the 1960s.", [2717]),
(S, "What is the capital of Khyber Pakhtunkhwa (KPK)?", ["Peshawar", "Mardan", "Abbottabad", "Swat"], 0, "Peshawar is the capital and largest city of Khyber Pakhtunkhwa.", "Peshawar is also the starting point of the Khyber Pass route to Afghanistan.", [2795]),
(S, "What is the capital of Portugal?", ["Madrid", "Porto", "Lisbon", "Barcelona"], 2, "Lisbon is the capital and largest city of Portugal.", "Porto is the second largest city of Portugal.", [2797]),
(S, "What is the capital of Sudan?", ["Khartoum", "Juba", "Cairo", "Addis Ababa"], 0, "Khartoum is the capital of Sudan, at the meeting of the Blue Nile and White Nile.", "Juba is the capital of South Sudan.", [2799]),
(S, "Which option correctly lists the capitals of Punjab, Sindh, Khyber Pakhtunkhwa and Balochistan in that order?", ["Lahore, Karachi, Peshawar, Quetta", "Lahore, Hyderabad, Peshawar, Quetta", "Rawalpindi, Karachi, Peshawar, Quetta", "Lahore, Karachi, Mardan, Gwadar"], 0, "The provincial capitals are Lahore (Punjab), Karachi (Sindh), Peshawar (KPK) and Quetta (Balochistan).", "Islamabad is the federal capital and is not a provincial capital.", [2514]),
(S, "Which city differs from the others: Lahore, Karachi, Rawalpindi, Quetta, Peshawar?", ["Quetta", "Rawalpindi", "Karachi", "Peshawar"], 1, "Lahore, Karachi, Quetta and Peshawar are provincial capitals. Rawalpindi is not.", "Rawalpindi is the headquarters of the Pakistan Army and lies next to Islamabad.", [3653]),
(S, "Who is the current ODI captain of Pakistan (as of October 2026)?", ["Babar Azam", "Mohammad Rizwan", "Shaheen Shah Afridi", "Salman Ali Agha"], 2, "Shaheen Shah Afridi was appointed Pakistan's ODI captain and was still leading the side in 2026.", "Babar Azam was ODI captain in 2022 to 2023 and Mohammad Rizwan led briefly after him.", [158, 101]),
(S, "For how many years did Hazrat Abdul Muttalib take care of the Holy Prophet (S.A.W.) after his mother passed away?", ["2 years", "4 years", "6 years", "8 years"], 0, "The Prophet (S.A.W.) was 6 when his mother died and 8 when his grandfather died, so Abdul Muttalib cared for him for about 2 years.", "After that, his uncle Abu Talib took care of him.", [1602, 1603]),
(S, "Who was the caretaker Chief Minister of Punjab in 2023 to 2024?", ["Mohsin Naqvi", "Hasan Askari", "Maryam Nawaz", "Parvez Elahi"], 0, "Mohsin Naqvi served as caretaker Chief Minister of Punjab from January 2023 until February 2024.", "Maryam Nawaz became elected Chief Minister of Punjab in February 2024.", [4194]),
(S, "Who was the caretaker Prime Minister of Pakistan in 2023 to 2024?", ["Anwaar-ul-Haq Kakar", "Shehbaz Sharif", "Nasirul Mulk", "Mohsin Naqvi"], 0, "Anwaar-ul-Haq Kakar led the caretaker government from August 2023 to March 2024.", "Shehbaz Sharif became Prime Minister again in March 2024.", [4201]),
(S, "Which country suffered the most deaths in World War II?", ["Germany", "United States", "Soviet Union", "United Kingdom"], 2, "The Soviet Union lost an estimated 24 to 27 million people, mostly on the Eastern Front against Germany.", "China also lost a very large number of people in the war.", [2219, 3699]),
(S, "What does the idiom 'to bell the cat' mean?", ["To take a dangerous task for the benefit of the group", "To make a loud noise", "To tell a secret", "To keep a pet"], 0, "The idiom comes from a fable in which mice wanted someone to tie a bell on the cat. It means to take on a risky task on behalf of others.", "The fable is attributed to Aesop.", [3020, 2538]),
(S, "What is the main natural source of ultraviolet (UV) rays?", ["The Moon", "The Sun", "Stars only", "Lightning only"], 1, "The Sun is the main natural source of UV rays. Most of the harmful UV is absorbed by the ozone layer.", "Too much UV exposure can cause sunburn and skin cancer.", [2522]),
(S, "Infections are caused by which of the following?", ["Harmful microorganisms such as bacteria and viruses", "Lack of exercise", "Lack of vitamins", "Too much sunlight"], 0, "Infections are caused by pathogens, which are harmful microorganisms like bacteria, viruses, fungi and parasites.", "Deficiency diseases, unlike infections, are caused by lack of nutrients.", [2220]),
(S, "Who was the companion of the Holy Prophet (S.A.W.) in the Cave of Thawr during the Hijrat?", ["Hazrat Umar (R.A.)", "Hazrat Ali (R.A.)", "Hazrat Abu Bakr (R.A.)", "Hazrat Uthman (R.A.)"], 2, "Hazrat Abu Bakr Siddiq (R.A.) accompanied the Prophet (S.A.W.) and hid with him in the Cave of Thawr during the migration to Madinah.", "Hazrat Ali (R.A.) stayed in Makkah in the Prophet's bed that night.", [4347]),
(S, "In which year was the second census of Pakistan held?", ["1951", "1961", "1972", "1981"], 1, "Pakistan's censuses were held in 1951, 1961, 1972, 1981, 1998, 2017 and 2023, so the second was in 1961.", "The 2023 census was the first digital census of Pakistan.", [3496]),
(S, "How many countries are there in Central Asia?", ["3", "4", "5", "6"], 2, "Central Asia has five countries: Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan and Uzbekistan.", "All five were part of the Soviet Union until 1991.", [1686, 252, 3742]),
]
